void bubbleRec(int[] a, int n) {
    if (n <= 1) return;
    boolean swapped = false;
    for (int j = 0; j < n - 1; j++)
        if (a[j] > a[j + 1]) { swap(a, j, j + 1); swapped = true; }
    if (swapped) bubbleRec(a, n - 1);
}

