void quickSort(int[] a, int lo, int hi) {
    if (lo >= hi) return;
    int p = hoare(a, lo, hi);
    quickSort(a, lo, p - 1);
    quickSort(a, p + 1, hi);
}
int hoare(int[] a, int lo, int hi) {
    int pivot = a[lo + (hi - lo) / 2], i = lo - 1, j = hi + 1;
    while (true) {
        do i++; while (a[i] < pivot);
        do j--; while (a[j] > pivot);
        if (i >= j) return j;
        swap(a, i, j);
    }
}

void mergeSort(int[] a, int lo, int hi) {
